def merge(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Sort intervals based on start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        # If the current interval overlaps or touches with the last merged interval, merge them
        if current[0] <= last[1]:
            last[1] = max(last[1], current[1])
        else:
            merged.append(current)

    return merged
```

```python
def contrast_ratio(hex1: str, hex2: str) -> float:
    def hex_to_rgb(h):
        h = h.lstrip('#')
        return tuple(int(h[i:i+2], 16) for i in (0, 2, 4))

    def relative_luminance(rgb):
        channels = [c / 255.0 for c in rgb]
        channels = [c ** 2.4 / 12.92 if c > 0.03928 else c / 12.92 for c in channels]
        return 0.2126 * channels[0] + 0.7152 * channels[1] + 0.0722 * channels[2]

    rgb1, rgb2 = hex_to_rgb(hex1), hex_to_rgb(hex2)
    lum1, lum2 = relative_luminance(rgb1), relative_luminance(rgb2)

    if lum1 < lum2:
        lum1, lum2 = lum2, lum1

    return round((lum1 + 0.05) / (lum2 + 0.05), 2)
