```python
def contrast_ratio(hex1: str, hex2: str) -> float:
    def parse_hex(h):
        h = h.lstrip('#')
        if len(h) == 3:
            # Expand shorthand to full six-digit form
            h = ''.join(c * 2 for c in h)
        if len(h) != 6:
            raise ValueError("Invalid hex color")
        r = int(h[0:2], 16)
        g = int(h[2:4], 16)
        b = int(h[4:6], 16)
        return (r, g, b)

    def linearize(c):
        c = c / 255.0
        if c <= 0.03928:
            return c / 12.92
        else:
            return ((c + 0.055) / 1.055) ** 2.4

    def luminance(rgb):
        r, g, b = rgb
        rl = linearize(r)
        gl = linearize(g)
        bl = linearize(b)
        # sRGB to relative luminance
        return 0.2126 * rl + 0.7152 * gl + 0.0722 * bl

    rgb1 = parse_hex(hex1)
    rgb2 = parse_hex(hex2)

    L1 = luminance(rgb1)
    L2 = luminance(rgb2)

    # Determine lighter and darker
    if L1 >= L2:
        lighter, darker = L1, L2
    else:
        lighter, darker = L2, L1

    ratio = (lighter + 0.05) / (darker + 0.05)
    return round(ratio, 2)
