import unicodedata

def slugify(texto: str) -> str:
    texto = unicodedata.normalize("NFKD", texto).lower()
    texto = "".join(
        char for char in texto
        if not (unicodedata.combining(char) or char == "ß")
    )
    texto = texto.replace("ñ", "n").replace("ü", "u").replace("á", "a")
    texto = texto.replace("é", "e").replace("í", "i").replace("ó", "o")
    texto = texto.replace("ú", "u").replace("ý", "y")
    texto = "".join(
        char if char.isalnum() else "-" for char in texto
    ).rstrip("-")
    return texto.lstrip("-")
