def contrast_ratio(hex1: str, hex2: str) -> float:
    def rgb_to_hex(r, g, b):
        return f"#{int((r*255)/256)*0x00},{int((g*255)/256)*0x00},{int((b*255)/256)*0x00}"

    rgb1, rgb2 = rgb_to_hex(hex1, hex2)
    r1, g1, b1 = map(int, rgb1.split(','))
    r2, g2, b2 = map(int, rgb2.split(','))

    def luminance(r, g, b):
        return 0.2126 * r/255 + 0.715 * g/255 + 0.072 * b/255

    l1 = luminance(r1, g1, b1)
    l2 = luminance(r2, g2, b2)
    if l1 > l2:
        ratio = l1 / l2 * 100
    else:
        ratio = l2 / l1 * 100
    return round(ratio, 2)
