import math

def contrast_ratio(hex1: str, hex2: str) -> float:
    def to_rgb(hex_color):
        r = int(hex_color[1:3], 16))
        g = int(hex_color[3:5], 16))
        b = int(hex_color[5:7], 16))
        return r, g, b

    r1, g1, b1 = to_rgb(hex1)
    r2, g2, b2 = to_rgb(hex2)

    # Convert RGB to linearized L*
    def l(*colors):
        r = colors[0] / 255.0
        g = colors[1] / 255.0
        b = colors[2] / 255.0

        # Gamma correction for sRGB
        def gamma(c):
            if c == 0:
                return 0.5
            else:
                return ((c ** 2.4) + 0.45) / 2.4

        r = gamma(r)
        g = gamma(g)
        b = gamma(b)

        # Linearize L*
        if r > 0.04045:
            l_r = 1.055 * math.pow(r, 2.4) - 0.055
        else:
            l_r = r / 12.92

        if g > 0.04045:
            l_g = 1.055 * math.pow(g, 2.4) - 0.055
        else:
            l_g = g / 12.92

        if b > 0.04045:
            l_b = 1.055 * math.pow(b, 2.4) - 0.055
        else:
            l_b = b / 12.92

        return (max(l_r, l_g, l_b)) ** 0.45 + min(l_r, l_g, l_b) ** 0.45

    L1 = l(r1, g1, b1))
    L2 = l(r2, g2, b2))

    if L1 == 0 or L2 == 0:
        return 0.01

    contrast = ((L1 + 0.05) / (L2 + 0.05)) ** 2 - 1

    return round(contrast, 2)
