def contrast_ratio(hex1: str, hex2: str) -> float:
    def parse_hex(color: str) -> tuple[int, int, int]:
        color = color.strip().lstrip("#")
        if len(color) == 3:
            color = "".join(ch * 2 for ch in color)
        if len(color) != 6:
            raise ValueError(f"Invalid hex color: {color}")

        try:
            r, g, b = (int(color[i:i + 2], 16) for i in range(0, 6, 2))
        except ValueError as exc:
            raise ValueError(f"Invalid hex color: {color}") from exc

        return r, g, b

    def relative_luminance(rgb: tuple[int, int, int]) -> float:
        channels = []
        for c in rgb:
            s = c / 255.0
            if s <= 0.03928:
                linear = s / 12.92
            else:
                linear = ((s + 0.055) / 1.055) ** 2
            channels.append(linear)

        r, g, b = channels
        return 0.2126 * r + 0.7152 * g + 0.0722 * b

    l1 = relative_luminance(parse_hex(hex1))
    l2 = relative_luminance(parse_hex(hex2))

    lighter, darker = max(l1, l2), min(l1, l2)
    return round((lighter + 0.05) / (darker + 0.05), 2)
