class DiagTests(unittest.TestCase):
    def test_decimal_addition_semantics(self):
        from decimal import Decimal
        self.assertEqual(Decimal("21.0") + Decimal("12"), Decimal("33.0"))

    def test_loop_assignment(self):
        total = Decimal("0")
        for v in [Decimal("21.0"), Decimal("12")]:
            print("[probe] before:", repr(total))
            total = v
            print("[probe] after :", repr(total))
