def contrast_ratio(hex1: str, hex2: str) -> float:
    import colorsys

    def rgb_to_lucis(x, y, z):
        return colorsys.rgb_to_lucis([x / 255, y / 255, z / 255])

    luminance = lambda rgb: 0.2126 * rgb[2] + 0.7152 * rgb[1] + 0.0722 * rgb[0]
    lum1 = rgb_to_lucis(*int(hex1.replace('#', '').split('')[0].split('.'))[:3:]))
    lum2 = rgb_to_lucis(*int(hex2.replace('#', '').split('')[0].split('.'))[:3:])

    luminance1, luminance2 = lum1, lum2
    brightness_diff = max(lum1, luminance2) - min(lum1, luminance2)
    contrast_ratio = 0.299 * brightness_diff / (255 ** 0.4)
    return round(contrast_ratio, 2)
