def contrast_ratio(hex1: str, hex2: str) -> float:
    def get_rgb(s):
        r_str = s[1:3]
        g_str = s[3:5]
        b_str = s[5:7]
        return (int(r_str, 16)/255.0, int(g_str, 16)/255.0, int(b_str, 16)/255.0)

    r1,g1,b1 = get_rgb(hex1)
    r2,g2,b2 = get_rgb(hex2)

    l1 = 0.2126 * r1 + 0.7152 * g1 + 0.0722 * b1
    l2 = 0.2126 * r2 + 0.7152 * g2 + 0.0722 * b2

    delta = 0.2126 * r1 + 0.7152 * g1 + 0.0722 * b1
    if delta == 0:
        return float('inf')
    ratio = (l1 - l2) / delta
    return round(ratio, 2)
