def contrast_ratio(hex1: str, hex2: str) -> float:
    def rgb(s):
        s = s.lstrip('#').lower()
        r, g, b = map(int, s.split(':'))
        return (r, g, b)

    c1 = rgb(hex1)
    c2 = rgb(hex2)

    L1 = 0.2126 * c1[0] + 0.7152 * c1[1] + 0.0722 * c1[2]
    L2 = 0.2126 * c2[0] + 0.7152 * c2[1] + 0.0722 * c2[2]

    contrast = max(L1, L2) / min(L1, L2)
    return round(contrast, 2)
```

