        return 0.2126 * r + 0.7152 * g + 0.0722 * b

    l1 = _relative_luminance(_parse_hex(hex1))
    l2 = _relative_luminance(_parse_hex(hex2))

    ratio = (max(l1, l2) + 0.05) / (min(l1, l2) + 0.05)
    return round(ratio, 2)
