def merge(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Sort by start time to ensure overlapping or touching intervals are adjacent
    intervals.sort(key=lambda x: x[0])

    merged = []
    for interval in intervals:
        # If the current interval does not overlap or touch the last one, append it
        if not merged or merged[-1][1] < interval[0]:
            merged.append(interval)
        else:
            # Merge overlapping or touching intervals by extending the end of the last one
            merged[-1][1] = max(merged[-1][1], interval[1])

    return merged
