PASSING = 70


def summarize(grades):
    """grades: dict of student -> score (0-100). A score of PASSING or more passes."""
    vals = list(grades.values())
    return {
        "count": len(vals),
        "mean": round(mean(vals), 2),
        "median": median(vals),
        "passed": sum(1 for v in vals if v >= PASSING),
    }
"}

