def contrast_ratio(hex1: str, hex2: str) -> float:
    def _parse_rgb(value):
        if not isinstance(value, str):
            raise TypeError("Hex color must be a string")

        h = value.strip()
        if h.startswith("#"):
            h = h[1:]

        # Remove any internal whitespace for leniency.
        h = "".join(h.split())

        if len(h) == 3 or len(h) == 4:  # shorthand; ignore alpha if present
            rgb_hex = ("".join(ch * 2 for ch in h))[:6]
        elif len(h) == 8:               # full RGBA/AABBGGBB-like input; take RGB part
            rgb_hex = h[:6]
        else:
            raise ValueError("Hex color must be RRGGBB, RGG or RGBA")

        return tuple(int(rgb_hex[i:i + 2], 16) for i in (0, 2, 4))

    def _luminance(rgb):
        channels = []
        for c in rgb:
            v = c / 255.0
            if v <= 0.04045:
                channels.append(v / 12.92)
            else:
                channels.append(((v + 0.055) / 1.055) ** 2.4)

        return (
            0.2126 * channels[0]
            + 0.7152 * channels[1]
            + 0.0722 * channels[2]
        )

    l1 = _luminance(_parse_rgb(hex1))
    l2 = _luminance(_parse_rgb(hex2))

    lighter, darker = max(l1, l2), min(l1, l2)
    return float(round((lighter + 0.05) / (darker + 0.05), 2))
