    """Returns True if a score of PASSING or more passes."""
    return score >= PASSING

def summarize(grades):
    """grades: dict of student -> score (0-100). A score of PASSING or more passes."""
    vals = list(grades.values())
    if not vals:
        return {
            "count": 0,
            "mean": 0.0,
            "median": 0.0,
            "passed": 0,
            "passing_threshold": PASSING,
        }
    return {
        "count": len(vals),
        "mean": round(mean(vals), 2),
        "median": median(vals),
        "passed": sum(1 for v in vals if is_passed(v)),
        "passing_threshold": PASSING,
    }
"}

