def contrast_ratio(hex1: str, hex2: str) -> float:
    def rgb_to_lum(rgb):
        # Convert RGB tuple (0-255) to relative luminance
        r, g, b = [c / 255.0 for c in rgb]
        # Gamma correction
        if r <= 0.03928:
            r = r / 12.92
        else:
            r = ((r + 0.055) / 1.055) ** 2.4
        if g <= 0.03928:
            g = g / 12.92
        else:
            g = ((g + 0.055) / 1.055) ** 2.4
        if b <= 0.03928:
            b = b / 12.92
        else:
            b = ((b + 0.055) / 1.055) ** 2.4
        # Relative luminance formula
        return 0.2126 * r + 0.7152 * g + 0.0722 * b

    def hex_to_rgb(hex_str):
        # Remove leading '#'
        h = hex_str.lstrip('#')
        if len(h) != 6:
            raise ValueError("Invalid hex color: must be 6 characters")
        try:
            r, g, b = (int(h[i:i+2], 16) for i in range(0, 6, 2))
        except ValueError:
            raise ValueError("Invalid hex color: contains non-hex characters")
        return (r, g, b)

    rgb1 = hex_to_rgb(hex1)
    rgb2 = hex_to_rgb(hex2)
    lum1 = rgb_to_lum(rgb1)
    lum2 = rgb_to_lum(rgb2)

    # Ensure lum1 >= lum2 for contrast ratio
    if lum1 < lum2:
        lum1, lum2 = lum2, lum1

    ratio = (lum1 + 0.05) / (lum2 + 0.05)
    return round(ratio, 2)
